<?php
/** CEO Index, saved executive briefing, and executive Q&A. PHP 5.6 compatible. */

use App\Core\Auth;
use App\Core\Db;
use App\Services\AiCeoIndexService;
use App\Services\AiExecutiveBriefService;
use App\Services\AiExecutiveQaService;
use App\Services\OpenAiResponsesClient;

require_once __DIR__ . '/../../services/OpenAiResponsesClient.php';
require_once __DIR__ . '/../../services/AiExecutiveBriefService.php';
require_once __DIR__ . '/../../services/AiCeoIndexService.php';
require_once __DIR__ . '/../../services/AiExecutiveQaService.php';

$ceoCanView=Auth::check()&&(Auth::isDevelopmentDepartment()||Auth::canManageEmployees()||Auth::userRole()==='executive');
$ceoCanManage=Auth::check()&&(Auth::isDevelopmentDepartment()||Auth::canManageEmployees());
if (!$ceoCanView) { http_response_code(403); echo '<div style="padding:16px;border:1px solid #fecaca;border-radius:14px;background:#fef2f2;color:#b91c1c;font-weight:800;">'.h('접근 권한이 없습니다.').'</div>'; return; }

if (!function_exists('cpms_ceo_money')) { function cpms_ceo_money($value) { return $value===null?'-':number_format((float)$value).'원'; } }
if (!function_exists('cpms_ceo_score')) { function cpms_ceo_score($value) { return $value===null?'-':number_format((float)$value,1).'점'; } }
if (!function_exists('cpms_ceo_rate')) { function cpms_ceo_rate($value) { return $value===null?'-':number_format((float)$value,1).'%'; } }

$ceoPdo=null; $ceoInitFailed=false;
try { $ceoPdo=Db::pdo(); } catch (Exception $e) { $ceoInitFailed=true; error_log('[AI CEO Index] db initialization failed'); }

if (empty($_SESSION['_csrf'])) {
    $ceoRandom=function_exists('openssl_random_pseudo_bytes')?@openssl_random_pseudo_bytes(32):false;
    if (!is_string($ceoRandom)||strlen($ceoRandom)<16) $ceoRandom=uniqid((string)mt_rand(),true).microtime(true).session_id();
    $_SESSION['_csrf']=hash('sha256',$ceoRandom);
}
$ceoCsrf=isset($_SESSION['_csrf'])?(string)$_SESSION['_csrf']:'';
$ceoActionResult=null;
if (isset($_SERVER['REQUEST_METHOD'])&&$_SERVER['REQUEST_METHOD']==='POST') {
    $token=isset($_POST['_csrf'])?(string)$_POST['_csrf']:''; $action=isset($_POST['action'])?trim((string)$_POST['action']):'';
    if (!csrf_check($token)) $ceoActionResult=array('ok'=>false,'message'=>'보안 토큰이 올바르지 않습니다.');
    else if ($action==='install') {
        if (!$ceoCanManage) $ceoActionResult=array('ok'=>false,'message'=>'설치 권한이 없습니다.');
        else if (!$ceoPdo) $ceoActionResult=array('ok'=>false,'message'=>'DB 연결 상태를 확인할 수 없습니다.');
        else {
            try {
                $indexInstall=AiCeoIndexService::installOrUpdate($ceoPdo); $qaInstall=AiExecutiveQaService::installOrUpdate($ceoPdo);
                $ceoActionResult=array('ok'=>!empty($indexInstall['ok'])&&!empty($qaInstall['ok']),'message'=>(isset($indexInstall['message'])?$indexInstall['message']:'').' '.(isset($qaInstall['message'])?$qaInstall['message']:''));
            } catch (Exception $e) { $ceoActionResult=array('ok'=>false,'message'=>'CEO Index 전용 테이블 설치 또는 확인에 실패했습니다.'); error_log('[AI CEO Index] install failed'); }
        }
    } else if ($action==='calculate') {
        if (!$ceoCanManage) $ceoActionResult=array('ok'=>false,'message'=>'계산 실행 권한이 없습니다.');
        else if (!$ceoPdo) $ceoActionResult=array('ok'=>false,'message'=>'DB 연결 상태를 확인할 수 없습니다.');
        else { try { $ceoActionResult=AiCeoIndexService::calculateLatest($ceoPdo,'MANUAL'); } catch (Exception $e) { $ceoActionResult=array('ok'=>false,'message'=>'CEO Index 계산 요청을 처리하지 못했습니다.'); error_log('[AI CEO Index] calculation request failed'); } }
    } else if ($action==='ask') {
        if (!$ceoPdo) $ceoActionResult=array('ok'=>false,'message'=>'DB 연결 상태를 확인할 수 없습니다.');
        else { try { $ceoActionResult=AiExecutiveQaService::ask($ceoPdo,isset($_POST['question'])?$_POST['question']:''); } catch (Exception $e) { $ceoActionResult=array('ok'=>false,'message'=>'대표 질문 요청을 처리하지 못했습니다.'); error_log('[OpenAI] task=EXECUTIVE_QA status=FAILED'); } }
    } else $ceoActionResult=array('ok'=>false,'message'=>'요청값이 올바르지 않습니다.');
}

$ceoStatus=array('db_available'=>(bool)$ceoPdo,'installed'=>false,'run'=>array(),'result'=>array(),'project'=>array(),'latest_risk'=>array(),'latest_result'=>array(),'latest_run'=>array());
$qaStatus=array('installed'=>false,'gpt_run_available'=>false,'qa_model'=>OpenAiResponsesClient::qaModel(),'qa_reasoning_effort'=>OpenAiResponsesClient::qaReasoningEffort(),'api_key_configured'=>OpenAiResponsesClient::hasApiKey(),'curl_available'=>function_exists('curl_init'));
if (!$ceoInitFailed) {
    try { $loaded=AiCeoIndexService::schemaStatus($ceoPdo); if (is_array($loaded)) $ceoStatus=array_merge($ceoStatus,$loaded); $loaded=AiExecutiveQaService::schemaStatus($ceoPdo); if (is_array($loaded)) $qaStatus=array_merge($qaStatus,$loaded); } catch (Exception $e) { $ceoInitFailed=true; error_log('[AI CEO Index] status failed'); }
}
$ceoResult=isset($ceoStatus['latest_result'])&&is_array($ceoStatus['latest_result'])?$ceoStatus['latest_result']:array();
$ceoBrief=array(); if ($ceoPdo) { try { $ceoBrief=AiExecutiveBriefService::latestBrief($ceoPdo); } catch (Exception $e) { $ceoBrief=array(); } }
$ceoBriefRisks=AiExecutiveBriefService::decodeData(isset($ceoBrief['top_risks_data'])?$ceoBrief['top_risks_data']:'');
$ceoBriefChecks=AiExecutiveBriefService::decodeData(isset($ceoBrief['check_today_data'])?$ceoBrief['check_today_data']:'');
$ceoBriefPositive=AiExecutiveBriefService::decodeData(isset($ceoBrief['positive_signals_data'])?$ceoBrief['positive_signals_data']:'');
$ceoBriefLimits=AiExecutiveBriefService::decodeData(isset($ceoBrief['data_limitations_data'])?$ceoBrief['data_limitations_data']:'');
$ceoPage=isset($_GET['page'])?max(1,(int)$_GET['page']):1; $ceoPerPage=50; $ceoProjects=array(); $ceoProjectCount=0;
if ($ceoPdo&&!empty($ceoResult)) { $ceoProjectCount=AiCeoIndexService::countProjects($ceoPdo,$ceoResult['analysis_date'],$ceoResult['target_ym']); }
$ceoTotalPages=max(1,(int)ceil($ceoProjectCount/$ceoPerPage)); if ($ceoPage>$ceoTotalPages) $ceoPage=$ceoTotalPages;
if ($ceoPdo&&!empty($ceoResult)) { $ceoProjects=AiCeoIndexService::listProjects($ceoPdo,$ceoResult['analysis_date'],$ceoResult['target_ym'],$ceoPage,$ceoPerPage); }
$ceoRecentAnswers=$ceoPdo?AiExecutiveQaService::latestAnswers($ceoPdo,5):array();
$ceoAnswer=isset($ceoActionResult['answer'])&&is_array($ceoActionResult['answer'])?$ceoActionResult['answer']:array();
$ceoAnswerPoints=AiExecutiveQaService::decodeData(isset($ceoAnswer['answer_points_data'])?$ceoAnswer['answer_points_data']:'');
$ceoAnswerProjects=AiExecutiveQaService::decodeData(isset($ceoAnswer['referenced_projects_data'])?$ceoAnswer['referenced_projects_data']:'');
$ceoAnswerChecks=AiExecutiveQaService::decodeData(isset($ceoAnswer['recommended_checks_data'])?$ceoAnswer['recommended_checks_data']:'');
$ceoAnswerLimits=AiExecutiveQaService::decodeData(isset($ceoAnswer['data_limitations_data'])?$ceoAnswer['data_limitations_data']:'');
$ceoEvidence=AiExecutiveQaService::evidenceCards($ceoAnswer,$ceoPdo);
$ceoWarnings=AiCeoIndexService::isInstalled($ceoPdo)?AiExecutiveQaService::decodeData(isset($ceoResult['warning_data'])?$ceoResult['warning_data']:''):array();
$ceoGrade=isset($ceoResult['ceo_index_grade'])?(string)$ceoResult['ceo_index_grade']:'INSUFFICIENT';
?>

<style>
