left:20px}.ci-list li{margin:7px 0;line-height:1.65}.ci-two{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.ci-question{width:100%;min-height:105px;padding:13px;border:1px solid #cbd5e1;border-radius:12px;resize:vertical}.ci-examples{display:flex;flex-wrap:wrap;gap:7px;margin:10px 0}.ci-example{padding:7px 10px;border:1px solid #cbd5e1;border-radius:999px;background:#fff;color:#334155;cursor:pointer}.ci-answer{padding:16px;border:1px solid #dbeafe;border-radius:14px;background:#f8fafc;margin-top:12px}.ci-evidence{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}.ci-evidence div{padding:11px;border:1px solid #e2e8f0;border-radius:11px;background:#fff}.ci-pages{display:flex;gap:8px;align-items:center;margin-top:13px}.ci-pages a{padding:8px 12px;border:1px solid #cbd5e1;border-radius:9px;text-decoration:none;color:#334155}.ci-btn[disabled]{opacity:.45;cursor:not-allowed}@media(max-width:1100px){.ci-grid{grid-template-columns:repeat(3,minmax(0,1fr))}.ci-evidence{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:680px){.ci-grid,.ci-two,.ci-evidence{grid-template-columns:1fr}.ci-hero{padding:18px}.ci-links,.ci-links .ci-btn,.ci-actions,.ci-actions form,.ci-actions .ci-btn{width:100%}}
