 <?php if($ceoInitFailed): ?><div class="ci-message error">CEO Index 상태를 불러오지 못했습니다.</div><?php elseif(empty($ceoStatus['db_available'])): ?><div class="ci-message error">DB 연결 상태를 확인할 수 없습니다.</div><?php elseif(empty($ceoStatus['installed'])): ?><div class="ci-note">CEO Index 테이블이 아직 설치되지 않았습니다.</div><?php elseif(empty($ceoStatus['latest_risk']['available'])): ?><div class="ci-note">CEO Index를 계산하려면 먼저 적자·원가율 위험분석을 실행해주세요.</div><?php elseif(empty($ceoResult)): ?><div class="ci-note">CEO Index 구조는 설치됐으며 최신 위험분석으로 계산할 수 있습니다.</div><?php endif; ?>
 <?php if(is_array($ceoActionResult)): ?><div class="ci-message <?php echo !empty($ceoActionResult['ok'])?'ok':'error'; ?>"><?php echo h(isset($ceoActionResult['message'])?$ceoActionResult['message']:'처리 결과를 확인할 수 없습니다.'); ?><?php if(!empty($ceoActionResult['cached'])): ?> (저장 결과 사용)<?php endif; ?></div><?php endif; ?>
 <?php foreach($ceoWarnings as $warning): ?><div class="ci-note"><?php echo h($warning); ?></div><?php endforeach; ?>

 <section class="ci-grid">
  <div class="ci-card"><div class="ci-label">CEO Index</div><div class="ci-value big"><?php echo h(cpms_ceo_score(isset($ceoResult['ceo_index_score'])?$ceoResult['ceo_index_score']:null)); ?></div><span class="ci-badge <?php echo h($ceoGrade); ?>"><?php echo h(AiCeoIndexService::gradeLabel($ceoGrade)); ?></span></div>
  <div class="ci-card"><div class="ci-label">직전 대비</div><div class="ci-value"><?php if(!isset($ceoResult['score_change'])||$ceoResult['score_change']===null): ?>비교자료 없음<?php elseif((float)$ceoResult['score_change']>0): ?><?php echo h(number_format((float)$ceoResult['score_change'],1)); ?>점 상승<?php elseif((float)$ceoResult['score_change']<0): ?><?php echo h(number_format(abs((float)$ceoResult['score_change']),1)); ?>점 하락<?php else: ?>변화 없음<?php endif; ?></div></div>
  <div class="ci-card"><div class="ci-label">분석 가능 비율</div><div class="ci-value"><?php echo h(cpms_ceo_rate(isset($ceoResult['coverage_rate'])?$ceoResult['coverage_rate']:null)); ?></div></div>
  <div class="ci-card"><div class="ci-label">최신 분석일 / 대상 월</div><div class="ci-value"><?php echo h(isset($ceoResult['analysis_date'])?$ceoResult['analysis_date']:'-'); ?> / <?php echo h(isset($ceoResult['target_ym'])?$ceoResult['target_ym']:'-'); ?></div></div>
  <div class="ci-card"><div class="ci-label">브리핑 / 질문 모델</div><div class="ci-value"><?php echo h(isset($ceoBrief['model_name'])?$ceoBrief['model_name']:'-'); ?><br><?php echo h(isset($qaStatus['qa_model'])?$qaStatus['qa_model']:'-'); ?></div></div>
  <div class="ci-card"><div class="ci-label">월 예상매출</div><div class="ci-value"><?php echo h(cpms_ceo_money(isset($ceoResult['monthly_sales_total'])?$ceoResult['monthly_sales_total']:null)); ?></div></div>
  <div class="ci-card"><div class="ci-label">월 예상투입비</div><div class="ci-value"><?php echo h(cpms_ceo_money(isset($ceoResult['monthly_forecast_input_total'])?$ceoResult['monthly_forecast_input_total']:null)); ?></div></div>
  <div class="ci-card"><div class="ci-label">월 예상손익</div><div class="ci-value"><?php echo h(cpms_ceo_money(isset($ceoResult['monthly_forecast_profit_total'])?$ceoResult['monthly_forecast_profit_total']:null)); ?></div></div>
  <div class="ci-card"><div class="ci-label">누적 예상손익</div><div class="ci-value"><?php echo h(cpms_ceo_money(isset($ceoResult['cumulative_projected_profit_total'])?$ceoResult['cumulative_projected_profit_total']:null)); ?></div></div>
  <div class="ci-card"><div class="ci-label">안정 / 관심 / 주의 / 긴급 / 부족</div><div class="ci-value"><?php echo h((int)(isset($ceoResult['normal_count'])?$ceoResult['normal_count']:0)); ?> / <?php echo h((int)(isset($ceoResult['watch_count'])?$ceoResult['watch_count']:0)); ?> / <?php echo h((int)(isset($ceoResult['warning_count'])?$ceoResult['warning_count']:0)); ?> / <?php echo h((int)(isset($ceoResult['critical_count'])?$ceoResult['critical_count']:0)); ?> / <?php echo h((int)(isset($ceoResult['insufficient_count'])?$ceoResult['insufficient_count']:0)); ?></div></div>
 </section>

 <?php if($ceoCanManage): ?><section class="ci-card ci-section"><h3>설치 및 계산</h3><div class="ci-actions"><form method="post" action="?r=admin%2Fai_ceo_index"><input type="hidden" name="_csrf" value="<?php echo h($ceoCsrf); ?>"><input type="hidden" name="action" value="install"><button class="ci-btn" type="submit">설치/확인</button></form><form method="post" action="?r=admin%2Fai_ceo_index"><input type="hidden" name="_csrf" value="<?php echo h($ceoCsrf); ?>"><input type="hidden" name="action" value="calculate"><button class="ci-btn secondary" type="submit"<?php echo empty($ceoStatus['installed'])||empty($ceoStatus['latest_risk']['available'])?' disabled':''; ?>>최신 위험분석으로 계산</button></form></div><div class="ci-note">CEO Index 계산에는 OpenAI API를 사용하지 않습니다. GET 화면 진입으로 계산하거나 브리핑을 생성하지 않습니다.</div></section><?php endif; ?>

